static void collect(struct TreeNode *node, int *vals, int *n) {
  if (!node) return;
  collect(node->left, vals, n);
  vals[(*n)++] = node->val;
  collect(node->right, vals, n);
}

static void assign(struct TreeNode *node, int *vals, int *idx) {
  if (!node) return;
  assign(node->left, vals, idx);
  node->val = vals[(*idx)++];
  assign(node->right, vals, idx);
}

void recoverTree(struct TreeNode *root) {
  int vals[1000], n = 0;
  collect(root, vals, &n);
  int i = 0;
  while (i < n - 1 && vals[i] < vals[i + 1]) i++;
  int j = n - 1;
  while (j > 0 && vals[j - 1] < vals[j]) j--;
  int t = vals[i];
  vals[i] = vals[j];
  vals[j] = t;
  int idx = 0;
  assign(root, vals, &idx);
}

class Solution {
  void collect(TreeNode *node, vector<int> &vals) {
    if (!node) return;
    collect(node->left, vals);
    vals.push_back(node->val);
    collect(node->right, vals);
  }

  void assign(TreeNode *node, vector<int> &vals, int &idx) {
    if (!node) return;
    assign(node->left, vals, idx);
    node->val = vals[idx++];
    assign(node->right, vals, idx);
  }

public:
  void recoverTree(TreeNode *root) {
    vector<int> vals;
    collect(root, vals);
    int n = vals.size();
    int i = 0;
    while (i < n - 1 && vals[i] < vals[i + 1]) i++;
    int j = n - 1;
    while (j > 0 && vals[j - 1] < vals[j]) j--;
    swap(vals[i], vals[j]);
    int idx = 0;
    assign(root, vals, idx);
  }
};

