class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private void collect(TreeNode node, List<Integer> vals) {
    if (node == null) return;
    collect(node.left, vals);
    vals.add(node.val);
    collect(node.right, vals);
  }

  private void assign(TreeNode node, List<Integer> vals, int[] idx) {
    if (node == null) return;
    assign(node.left, vals, idx);
    node.val = vals.get(idx[0]++);
    assign(node.right, vals, idx);
  }

  public void recoverTree(TreeNode root) {
    List<Integer> vals = new ArrayList<>();
    collect(root, vals);
    int n = vals.size();
    int i = 0;
    while (i < n - 1 && vals.get(i) < vals.get(i + 1)) i++;
    int j = n - 1;
    while (j > 0 && vals.get(j - 1) < vals.get(j)) j--;
    int t = vals.get(i);
    vals.set(i, vals.get(j));
    vals.set(j, t);
    assign(root, vals, new int[] { 0 });
  }
}

impl Solution {
  fn collect(node: &Option<Box<TreeNode>>, vals: &mut Vec<i32>) {
    if let Some(n) = node {
      Self::collect(&n.left, vals);
      vals.push(n.val);
      Self::collect(&n.right, vals);
    }
  }

  fn assign(node: &mut Option<Box<TreeNode>>, vals: &[i32], idx: &mut usize) {
    if let Some(n) = node {
      Self::assign(&mut n.left, vals, idx);
      n.val = vals[*idx];
      *idx += 1;
      Self::assign(&mut n.right, vals, idx);
    }
  }

  pub fn recover_tree(root: &mut Option<Box<TreeNode>>) {
    let mut vals = vec![];
    Self::collect(root, &mut vals);
    let n = vals.len();
    let mut i = 0;
    while i < n - 1 && vals[i] < vals[i + 1] {
      i += 1;
    }
    let mut j = n - 1;
    while j > 0 && vals[j - 1] < vals[j] {
      j -= 1;
    }
    vals.swap(i, j);
    let mut idx = 0;
    Self::assign(root, &vals, &mut idx);
  }
}

const recoverTree = (root: TreeNode | null): void => {
  const vals: number[] = [];
  const collect = (node: TreeNode | null) => {
    if (!node) return;
    collect(node.left);
    vals.push(node.val);
    collect(node.right);
  };
  collect(root);
  const n = vals.length;
  let i = 0;
  while (i < n - 1 && vals[i] < vals[i + 1]) i++;
  let j = n - 1;
  while (j > 0 && vals[j - 1] < vals[j]) j--;
  [vals[i], vals[j]] = [vals[j], vals[i]];
  let idx = 0;
  const assign = (node: TreeNode | null) => {
    if (!node) return;
    assign(node.left);
    node.val = vals[idx++];
    assign(node.right);
  };
  assign(root);
};
